import React from "react";
import { AbsoluteFill, Img, useCurrentFrame, interpolate, spring } from "remotion";
import { COLORS, FONTS, headlineGradient } from "../style-tokens";
import type { PrimitiveProps } from "../primitives";

const COUNT = 5;

const LequeImagens: React.FC<PrimitiveProps> = ({ anim, fps, dark, format, frame }) => {
  const f = useCurrentFrame();
  const params = (anim.params ?? {}) as Record<string, unknown>;
  const total = Math.max(1, Math.round((anim.end - anim.start) * fps));
  const W = frame.width;
  const H = frame.height;

  // `src` is the pipeline's slot; src2..src5 (or a srcs array) carry the rest.
  const list = Array.isArray(params.srcs) ? (params.srcs as unknown[]) : [];
  const srcs = Array.from({ length: COUNT }, (_, i) => {
    const v = i === 0 ? params.src : params[`src${i + 1}`];
    return String(v ?? list[i] ?? "");
  });

  const text = String(anim.text ?? "").trim();
  const reserve = text ? H * (format === "portrait" ? 0.16 : 0.18) : 0;
  const areaH = H - reserve;

  const L =
    format === "portrait"
      ? { w: W * 0.64, step: 6, spread: W * 0.04 }
      : format === "half"
        ? { w: areaH * 0.74 * 0.8, step: 9, spread: W * 0.08 }
        : { w: areaH * 0.8 * 0.8, step: 11, spread: W * 0.13 };
  const cardW = Math.min(L.w, W * 0.64);
  const cardH = Math.min(cardW * 1.25, areaH * 0.84);
  const border = Math.max(4, Math.round(cardW * 0.012));

  // Cards land one at a time across the first ~70% of the layer.
  const gap = (total * 0.7) / COUNT;
  const exit = interpolate(f, [total - 8, total], [1, 0], { extrapolateLeft: "clamp", extrapolateRight: "clamp" });

  const fontSize = Math.min(
    W * (format === "landscape" ? 0.045 : 0.085),
    (reserve * 0.8) / Math.max(1, Math.ceil(text.length / 22)),
  );

  return (
    <AbsoluteFill style={{ fontFamily: FONTS.display, opacity: exit }}>
      {text ? (
        <div
          style={{
            position: "absolute",
            top: 0,
            left: W * 0.067,
            right: W * 0.067,
            minHeight: reserve,
            display: "flex",
            alignItems: "center",
            justifyContent: "center",
            textAlign: "center",
          }}
        >
          <span
            style={{
              fontSize,
              lineHeight: 0.98,
              fontWeight: FONTS.displayWeight,
              fontStyle: "italic",
              textTransform: "uppercase",
              backgroundImage: headlineGradient(),
              WebkitBackgroundClip: "text",
              backgroundClip: "text",
              color: "transparent",
              opacity: interpolate(f, [0, 10], [0, 1], { extrapolateRight: "clamp" }),
            }}
          >
            {text}
          </span>
        </div>
      ) : null}

      <div style={{ position: "absolute", top: reserve, left: 0, width: W, height: areaH }}>
        {srcs.map((src, i) => {
          const p = spring({ frame: f - i * gap, fps, config: { damping: 16, stiffness: 110 } });
          const offset = i - (COUNT - 1) / 2;
          const angle = interpolate(p, [0, 1], [0, offset * L.step]);
          const x = interpolate(p, [0, 1], [0, offset * L.spread]);
          const y = interpolate(p, [0, 1], [areaH * 0.6, 0]);
          return (
            <div
              key={i}
              style={{
                position: "absolute",
                left: (W - cardW) / 2,
                top: (areaH - cardH) / 2,
                width: cardW,
                height: cardH,
                transformOrigin: "50% 130%",
                transform: `translate(${x}px, ${y}px) rotate(${angle}deg)`,
                opacity: interpolate(p, [0, 0.25], [0, 1], { extrapolateRight: "clamp" }),
                border: `${border}px solid rgba(255,255,255,1)`,
                boxSizing: "border-box",
                backgroundColor: COLORS.vellum,
                zIndex: i,
                overflow: "hidden",
                display: "flex",
                alignItems: "center",
                justifyContent: "center",
              }}
            >
              {src ? (
                <Img src={src} style={{ width: "100%", height: "100%", objectFit: "cover" }} />
              ) : (
                <span
                  style={{
                    fontSize: cardW * 0.09,
                    fontStyle: "italic",
                    fontWeight: FONTS.displayWeight,
                    color: dark ? COLORS.mutedOnDark : COLORS.mutedOnLight,
                    textTransform: "uppercase",
                  }}
                >
                  {`Imagem ${i + 1}`}
                </span>
              )}
            </div>
          );
        })}
      </div>
    </AbsoluteFill>
  );
};

export default LequeImagens;

