import React from "react";
import { AbsoluteFill, Img, useCurrentFrame, interpolate, spring } from "remotion";
import { COLORS, FONTS, STYLE, headlineGradient } from "../style-tokens";
import type { PrimitiveProps } from "../primitives";

const LequeImagens: React.FC<PrimitiveProps> = ({ anim, fps, dark, format, frame }) => {
  const f = useCurrentFrame();
  const W = frame.width;
  const H = frame.height;
  const dur = Math.max(1, Math.round((anim.end - anim.start) * fps));

  // Images: an optional `srcs` list, else the pipeline's single `src` repeated, else placeholders.
  const src = String(anim.params?.src ?? "");
  const rawSrcs = anim.params?.srcs;
  const list = Array.isArray(rawSrcs) ? rawSrcs.map((s) => String(s ?? "")).filter(Boolean).slice(0, 8) : [];
  const countParam = Number(anim.params?.count);
  const n = list.length > 0 ? list.length : Math.min(7, Math.max(3, Number.isFinite(countParam) ? Math.round(countParam) : 5));
  const images = list.length > 0 ? list : Array.from({ length: n }, () => src);

  const text = String(anim.text ?? "").trim();
  const textColor = dark ? COLORS.textOnDark : COLORS.textOnLight;

  const cardH = Math.min(H * (format === "portrait" ? 0.34 : format === "half" ? 0.5 : 0.56), W * 0.5) * (text ? 1 : 1.12);
  const cardW = cardH / 1.3;
  const maxAngle = format === "landscape" ? 30 : 22;
  const xStep = format === "landscape" ? cardW * 0.32 : cardW * 0.08;
  const border = Math.max(3, Math.round(W * 0.005));

  const stagger = Math.max(1, Math.min(fps * 0.35, (dur * 0.6) / n));
  const exitLen = Math.min(fps * 0.4, dur * 0.2);
  const exit = interpolate(f, [dur - exitLen, dur], [1, 0], { extrapolateLeft: "clamp", extrapolateRight: "clamp" });

  const baseFont = Math.min(W, H) * (format === "half" ? 0.07 : 0.08);
  const fontSize = baseFont * Math.min(1, Math.max(0.5, 18 / Math.max(1, text.length)));
  const captionIn = spring({ frame: f - n * stagger, fps, config: { damping: 200 } });
  const gradient = STYLE.headline === "gradient";

  return (
    <AbsoluteFill style={{ fontFamily: FONTS.display, alignItems: "center", justifyContent: "center", opacity: exit }}>
      <div style={{ display: "flex", flexDirection: "column", alignItems: "center", gap: H * 0.04, width: "100%" }}>
        <div style={{ position: "relative", width: "100%", height: cardH * 1.08 }}>
          {images.map((img, i) => {
            const p = spring({ frame: f - i * stagger, fps, config: { damping: 14, stiffness: 120, mass: 0.8 } });
            const rel = n > 1 ? i / (n - 1) - 0.5 : 0;
            const angle = rel * 2 * maxAngle * p;
            const x = rel * (n - 1) * xStep * p;
            const y = (1 - p) * cardH * 0.5;
            return (
              <div
                key={i}
                style={{
                  position: "absolute",
                  left: "50%",
                  bottom: 0,
                  width: cardW,
                  height: cardH,
                  marginLeft: -cardW / 2,
                  transformOrigin: "50% 100%",
                  transform: `translateX(${x}px) translateY(${y}px) rotate(${angle}deg)`,
                  opacity: interpolate(p, [0, 0.3], [0, 1], { extrapolateRight: "clamp" }),
                  border: `${border}px solid ${textColor}`,
                  borderRadius: 0,
                  overflow: "hidden",
                  background: COLORS.vellum,
                }}
              >
                {img ? (
                  <Img src={img} style={{ width: "100%", height: "100%", objectFit: "cover" }} />
                ) : (
                  <div style={{ position: "absolute", inset: 0 }}>
                    <div
                      style={{
                        position: "absolute",
                        left: "-20%",
                        right: "-20%",
                        top: "58%",
                        height: "60%",
                        background: `${COLORS.teal}55`,
                        transform: "rotate(-11deg)",
                      }}
                    />
                    <div
                      style={{
                        position: "absolute",
                        inset: "8%",
                        border: `${Math.max(2, border / 2)}px solid ${COLORS.mutedOnLight}55`,
                      }}
                    />
                  </div>
                )}
              </div>
            );
          })}
        </div>
        {text ? (
          <div
            style={{
              maxWidth: "86%",
              textAlign: "center",
              fontSize,
              lineHeight: 0.98,
              fontWeight: FONTS.displayWeight,
              fontStyle: "italic",
              textTransform: "uppercase",
              color: gradient ? "transparent" : textColor,
              backgroundImage: gradient ? headlineGradient() : undefined,
              WebkitBackgroundClip: gradient ? "text" : undefined,
              backgroundClip: gradient ? "text" : undefined,
              opacity: captionIn,
              transform: `translateY(${(1 - captionIn) * fontSize * 0.6}px)`,
              overflowWrap: "break-word",
            }}
          >
            {text}
          </div>
        ) : null}
      </div>
    </AbsoluteFill>
  );
};

export default LequeImagens;

import React from "react";
import { AbsoluteFill, Img, useCurrentFrame, interpolate, spring } from "remotion";
import { COLORS, FONTS, STYLE, headlineGradient } from "../style-tokens";
import type { PrimitiveProps } from "../primitives";

const LequeImagensGrande: React.FC<PrimitiveProps> = ({ anim, fps, dark, format, frame }) => {
  const f = useCurrentFrame();
  const W = frame.width;
  const H = frame.height;
  const dur = Math.max(1, Math.round((anim.end - anim.start) * fps));

  // Images: optional `srcs` list, else the pipeline's single `src` repeated, else placeholders.
  const src = String(anim.params?.src ?? "");
  const rawSrcs = anim.params?.srcs;
  const list = Array.isArray(rawSrcs) ? rawSrcs.map((s) => String(s ?? "")).filter(Boolean).slice(0, 7) : [];
  const countParam = Number(anim.params?.count);
  const n = list.length > 0 ? list.length : Math.min(6, Math.max(2, Number.isFinite(countParam) ? Math.round(countParam) : 4));
  const images = list.length > 0 ? list : Array.from({ length: n }, () => src);

  const text = String(anim.text ?? "").trim();
  const textColor = dark ? COLORS.textOnDark : COLORS.textOnLight;

  // Big cards: most of the frame, shaped for each format.
  const shrink = text ? 0.84 : 1;
  const cardH =
    (format === "portrait"
      ? Math.min(H * 0.56, W * 0.74 * 1.3)
      : format === "half"
        ? Math.min(H * 0.78, W * 0.6 * 1.25)
        : Math.min(H * 0.78, W * 0.56 * 0.8)) * shrink;
  const cardW = format === "portrait" ? cardH / 1.3 : format === "half" ? cardH / 1.25 : cardH / 0.8;
  const border = Math.max(3, Math.round(Math.min(W, H) * 0.006));

  // Fan pivot sits far below the cards; spread so the outer cards stay mostly on screen.
  const pivot = cardH * 2.4;
  const reach = Math.min(1, ((W - cardW) / 2 + cardW * 0.2) / pivot);
  const maxAngle = (Math.asin(reach) * 180) / Math.PI;
  const step = n > 1 ? (2 * maxAngle) / (n - 1) : 0;

  // One card at a time across ~65% of the layer.
  const stagger = Math.max(fps * 0.25, Math.min(fps * 0.9, (dur * 0.65) / n));
  const progress = images.map((_, i) =>
    spring({ frame: f - i * stagger, fps, config: { damping: 16, stiffness: 110, mass: 0.9 } }),
  );
  const shown = progress.reduce((a, p) => a + p, 0);

  const exitLen = Math.min(fps * 0.4, dur * 0.2);
  const exit = interpolate(f, [dur - exitLen, dur], [1, 0], { extrapolateLeft: "clamp", extrapolateRight: "clamp" });

  const baseFont = Math.min(W, H) * (format === "half" ? 0.065 : 0.075);
  const fontSize = baseFont * Math.min(1, Math.max(0.5, 20 / Math.max(1, text.length)));
  const captionIn = spring({ frame: f - n * stagger, fps, config: { damping: 200 } });
  const gradient = STYLE.headline === "gradient";

  return (
    <AbsoluteFill style={{ fontFamily: FONTS.display, alignItems: "center", justifyContent: "center", opacity: exit }}>
      <div style={{ display: "flex", flexDirection: "column", alignItems: "center", gap: H * 0.03, width: "100%" }}>
        <div style={{ position: "relative", width: "100%", height: cardH * 1.04 }}>
          {images.map((img, i) => {
            const p = progress[i];
            // Fan re-centres as each card arrives.
            const angle = (i - (Math.max(1, shown) - 1) / 2) * step;
            return (
              <div
                key={i}
                style={{
                  position: "absolute",
                  left: "50%",
                  bottom: 0,
                  width: cardW,
                  height: cardH,
                  marginLeft: -cardW / 2,
                  transformOrigin: `50% ${(pivot / cardH) * 100 + 100}%`,
                  transform: `translateY(${(1 - p) * H * 0.9}px) rotate(${angle + (1 - p) * 12}deg)`,
                  opacity: interpolate(p, [0, 0.2], [0, 1], { extrapolateRight: "clamp" }),
                  border: `${border}px solid ${textColor}`,
                  overflow: "hidden",
                  background: COLORS.vellum,
                }}
              >
                {img ? (
                  <Img src={img} style={{ width: "100%", height: "100%", objectFit: "cover" }} />
                ) : (
                  <div style={{ position: "absolute", inset: 0 }}>
                    <div
                      style={{
                        position: "absolute",
                        left: "-20%",
                        right: "-20%",
                        top: "60%",
                        height: "60%",
                        background: `${COLORS.teal}55`,
                        transform: "rotate(-11deg)",
                      }}
                    />
                    <div
                      style={{
                        position: "absolute",
                        inset: "8%",
                        border: `${Math.max(2, border / 2)}px solid ${COLORS.mutedOnLight}55`,
                      }}
                    />
                  </div>
                )}
              </div>
            );
          })}
        </div>
        {text ? (
          <div
            style={{
              maxWidth: "86%",
              textAlign: "center",
              fontSize,
              lineHeight: 0.98,
              fontWeight: FONTS.displayWeight,
              fontStyle: "italic",
              textTransform: "uppercase",
              color: gradient ? "transparent" : textColor,
              backgroundImage: gradient ? headlineGradient() : undefined,
              WebkitBackgroundClip: gradient ? "text" : undefined,
              backgroundClip: gradient ? "text" : undefined,
              opacity: captionIn,
              transform: `translateY(${(1 - captionIn) * fontSize * 0.6}px)`,
              overflowWrap: "break-word",
            }}
          >
            {text}
          </div>
        ) : null}
      </div>
    </AbsoluteFill>
  );
};

export default LequeImagensGrande;
